import { describe, expect, it } from "vitest";
import { runValuation } from "../application/run-valuation";
import { fixtureCycleValuation } from "../infrastructure/fixture-cycle-valuation";
import { deriveCycleNormalization } from "./cycle-normalization";

/** Values transcribed from normearn.xls, not generated by this engine. */
describe("cycle normalization independent oracles", () => {
  it("reconciles the five annual ratios of normearn.xls and names its pooled weighting difference", () => {
    const input = fixtureCycleValuation();
    const cycle = input.cycleNormalization!;
    const sales = ["2032", "2376", "2779", "3155", "3248"];
    const ebit = ["186", "454", "529", "448", "383"];
    cycle.history.forEach((year, index) => {
      year.revenue!.value = sales[index]!;
      year.ebit!.value = ebit[index]!;
    });
    // The workbook's current sales B15 are 12154; its five rows precede that base.
    const result = deriveCycleNormalization(cycle, "12154", "3455", 5);
    const spreadsheetMargins = [
      0.0915354330708662, 0.191077441077441, 0.190356243252969,
      0.141996830427892, 0.117918719211823,
    ];
    result.annualMargins.forEach((value, index) =>
      expect(Number(value)).toBeCloseTo(spreadsheetMargins[index]!, 14),
    );
    expect(Number(result.historicalMargin)).toBeCloseTo(
      0.14657693340819816,
      14,
    );
    expect(Number(result.normalizedBaseEbit)).toBeCloseTo(
      1781.4960486432405,
      10,
    );
    // G21 = SUM(EBIT)/SUM(sales), not AVERAGE(B21:F21).
    const workbookPooledMargin = 0.147167034584253;
    const workbookD14 = 1788.66813833701;
    expect(Number(result.historicalMargin)).toBeLessThan(workbookPooledMargin);
    expect(Number(result.normalizedBaseEbit) - workbookD14).toBeCloseTo(
      -7.1720896937695,
      9,
    );
  });

  it("matches a constant-cashflow perpetuity independently of the projection loop", () => {
    const input = fixtureCycleValuation();
    input.cycleNormalization!.convergenceYears = 1;
    input.periods.forEach((year) => {
      year.revenueGrowth = "0";
      year.ebitMargin = "0.106";
    });
    input.terminal.growth = "0";
    input.sensitivity = null;
    if (input.failureRisk.basis !== "rating_table")
      throw new Error("Expected rating fixture");
    input.failureRisk.parameter.value = "0";
    const result = runValuation(input, {
      now: () => "2025-07-01T00:00:00.000Z",
      newValuationRunId: () => "11111111-1111-4111-8111-111111111111",
    });
    // EBIT 96m * .106, tax 25%, no growth/reinvestment: 7.632m / .09.
    expect(result.status).toBe("requires_review");
    expect(Number(result.result!.enterpriseValue)).toBeCloseTo(84_800_000, 6);
    expect(
      result.result!.periods.every((period) => period.fcff === "7632000"),
    ).toBe(true);
  });
});
